:root {
  color-scheme: light;
  font-family: system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
  font-size: 16px;
  color: #183b3a;
  background: #e8efe7;
}

* { box-sizing: border-box; }
body {
  min-width: 360px;
  min-height: 100vh;
  margin: 0;
  padding: 32px 16px;
  display: grid;
  place-items: center;
  background-color: #e8efe7;
  background-image: radial-gradient(#c5d4c6 1px, transparent 1px);
  background-size: 18px 18px;
}
.counter {
  width: min(100%, 520px);
  padding: clamp(24px, 6vw, 44px);
  border: 3px solid #183b3a;
  border-radius: 18px;
  background: #fffdf5;
  box-shadow: 8px 8px 0 #183b3a;
}
.header { text-align: center; }
.pixel-mark {
  width: 40px;
  height: 40px;
  margin: 0 auto 18px;
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 4px;
  transform: rotate(-4deg);
}
.pixel-mark span { background: #e2a541; border: 2px solid #183b3a; }
.pixel-mark span:nth-child(2), .pixel-mark span:nth-child(3) { background: #4e8b72; }
.eyebrow, .section-label, footer {
  margin: 0;
  color: #54726a;
  font-size: .8rem;
  font-weight: 800;
  letter-spacing: .12em;
}
h1 { margin: 8px 0 6px; font-size: clamp(2rem, 8vw, 2.7rem); line-height: 1.1; letter-spacing: -.04em; }
.subtitle { margin: 0; color: #54726a; font-size: 1rem; }
.serving-panel {
  margin: 30px 0 20px;
  padding: 20px;
  border: 2px dashed #4e8b72;
  border-radius: 12px;
  background: #eef4e9;
  text-align: center;
}
.serving-number { margin: 2px 0 0; color: #183b3a; font-size: clamp(3.5rem, 16vw, 5.5rem); font-weight: 850; line-height: 1; font-variant-numeric: tabular-nums; }
.actions { display: grid; grid-template-columns: 1fr 1fr; gap: 12px; }
.button {
  min-height: 54px;
  padding: 12px 16px;
  border: 2px solid #183b3a;
  border-radius: 9px;
  font: inherit;
  font-weight: 750;
  cursor: pointer;
  transition: transform 100ms ease, box-shadow 100ms ease, background-color 100ms ease;
}
.button-primary { color: #183b3a; background: #e2a541; box-shadow: 0 4px 0 #183b3a; }
.button-secondary { color: #fffdf5; background: #35765f; box-shadow: 0 4px 0 #183b3a; }
.button:hover { transform: translateY(-2px); filter: brightness(1.04); }
.button:active { transform: translateY(3px); box-shadow: 0 1px 0 #183b3a; }
.button:focus-visible { outline: 4px solid #e2a541; outline-offset: 4px; }
.status { min-height: 24px; margin: 15px 0 22px; color: #54726a; text-align: center; }
.queue-panel { padding-top: 20px; border-top: 1px solid #d6e0d3; }
.queue-heading-row { display: flex; align-items: center; justify-content: space-between; gap: 12px; }
h2 { margin: 0; font-size: 1.2rem; }
.count-badge { padding: 6px 10px; border-radius: 999px; color: #183b3a; background: #e8efe7; font-size: .9rem; font-weight: 700; white-space: nowrap; }
.waiting-list { max-height: 180px; margin: 14px 0 0; padding: 0 4px 0 0; display: flex; flex-wrap: wrap; align-content: flex-start; gap: 8px; overflow-y: auto; list-style: none; }
.waiting-list li:not(.empty-state) { min-width: 54px; padding: 9px 12px; border: 1px solid #b9cec0; border-radius: 8px; background: #f3f6ed; text-align: center; font-weight: 750; font-variant-numeric: tabular-nums; }
.empty-state { width: 100%; padding: 14px 10px; color: #71877d; text-align: center; }
footer { margin-top: 25px; text-align: center; font-size: .7rem; }
@media (max-width: 420px) {
  body { padding: 20px 14px; }
  .counter { padding: 24px 20px; box-shadow: 5px 5px 0 #183b3a; }
  .actions { grid-template-columns: 1fr; gap: 10px; }
  .serving-panel { margin-top: 24px; }
}

const waiting = [];
let nextNumber = 1;

const servingNumber = document.getElementById('serving-number');
const waitingCount = document.getElementById('waiting-count');
const waitingList = document.getElementById('waiting-list');
const status = document.getElementById('status');

function renderQueue() {
  waitingCount.textContent = String(waiting.length);
  waitingList.replaceChildren();

  if (waiting.length === 0) {
    const empty = document.createElement('li');
    empty.className = 'empty-state';
    empty.textContent = 'No tickets waiting yet';
    waitingList.append(empty);
    return;
  }

  for (const number of waiting) {
    const item = document.createElement('li');
    item.textContent = `#${number}`;
    waitingList.append(item);
  }
}

document.getElementById('take-ticket').addEventListener('click', () => {
  const number = nextNumber++;
  waiting.push(number);
  renderQueue();
  status.textContent = `Ticket #${number} added to the waiting list.`;
});

document.getElementById('serve-next').addEventListener('click', () => {
  if (waiting.length === 0) {
    status.textContent = 'There are no tickets waiting to be served.';
    return;
  }

  const number = waiting.shift();
  servingNumber.textContent = `#${number}`;
  renderQueue();
  status.textContent = `Now serving ticket #${number}.`;
});
